-- Astrogation (Galaxy tab) data: DK-map systems, Wookieepedia hyperlanes, nav hazards, per-campaign GM pins.
-- Rows for the three ref_* tables are seeded from data/astrogation/wook/seed.sql (generated by
-- scripts/astrogation/wook/build-seed.ts) through the same path as a migration; there is no service-role import.

-- ── 1. Reference tables (read-only to clients) ──────────────────────────────
CREATE TABLE IF NOT EXISTS ref_systems (
  id      text PRIMARY KEY,                 -- graph id, e.g. 'coruscant-l-9'
  name    text NOT NULL,
  x       real NOT NULL,                    -- DK map px (4000 x 4000)
  y       real NOT NULL,
  region  text,
  sector  text,
  on_lane boolean NOT NULL DEFAULT false,
  source  text NOT NULL DEFAULT 'dk-map'
);

-- Lane data is compiled from Wookieepedia (CC BY-SA 3.0). source_url + source_revision are the attribution.
CREATE TABLE IF NOT EXISTS ref_hyperlanes (
  id              bigserial PRIMARY KEY,
  a               text NOT NULL REFERENCES ref_systems(id),
  b               text NOT NULL REFERENCES ref_systems(id),
  route_name      text NOT NULL,
  lane_class      text NOT NULL CHECK (lane_class IN ('major', 'minor')),
  length_px       real NOT NULL,
  edition         text CHECK (edition IN ('canon', 'legends')),
  source_url      text,
  source_revision bigint,
  UNIQUE (a, b, route_name)
);
COMMENT ON TABLE ref_hyperlanes IS 'Hyperlane edges compiled from Wookieepedia route articles (CC BY-SA 3.0, https://starwars.fandom.com). source_url + source_revision identify the article revision.';

CREATE TABLE IF NOT EXISTS ref_nav_hazards (
  id        bigserial PRIMARY KEY,
  system_id text NOT NULL REFERENCES ref_systems(id),
  upgrades  integer NOT NULL,
  note      text NOT NULL DEFAULT '',
  UNIQUE (system_id, note)
);

CREATE INDEX IF NOT EXISTS ref_hyperlanes_a_idx ON ref_hyperlanes (a);
CREATE INDEX IF NOT EXISTS ref_hyperlanes_b_idx ON ref_hyperlanes (b);

ALTER TABLE ref_systems     ENABLE ROW LEVEL SECURITY;
ALTER TABLE ref_hyperlanes  ENABLE ROW LEVEL SECURITY;
ALTER TABLE ref_nav_hazards ENABLE ROW LEVEL SECURITY;

-- Read policies match migration 135 (separate anon and authenticated SELECT, USING true).
-- No INSERT/UPDATE/DELETE policy on purpose: only the service role / MCP seed path can write.
DROP POLICY IF EXISTS "anon read ref_systems" ON ref_systems;
CREATE POLICY "anon read ref_systems" ON ref_systems FOR SELECT TO anon USING (true);
DROP POLICY IF EXISTS "auth read ref_systems" ON ref_systems;
CREATE POLICY "auth read ref_systems" ON ref_systems FOR SELECT TO authenticated USING (true);

DROP POLICY IF EXISTS "anon read ref_hyperlanes" ON ref_hyperlanes;
CREATE POLICY "anon read ref_hyperlanes" ON ref_hyperlanes FOR SELECT TO anon USING (true);
DROP POLICY IF EXISTS "auth read ref_hyperlanes" ON ref_hyperlanes;
CREATE POLICY "auth read ref_hyperlanes" ON ref_hyperlanes FOR SELECT TO authenticated USING (true);

DROP POLICY IF EXISTS "anon read ref_nav_hazards" ON ref_nav_hazards;
CREATE POLICY "anon read ref_nav_hazards" ON ref_nav_hazards FOR SELECT TO anon USING (true);
DROP POLICY IF EXISTS "auth read ref_nav_hazards" ON ref_nav_hazards;
CREATE POLICY "auth read ref_nav_hazards" ON ref_nav_hazards FOR SELECT TO authenticated USING (true);

-- ── 2. Per-campaign pins (uncharted points the GM drops on the galaxy map) ──
-- The app has no Supabase Auth identity (players.user_id is NULL for every row), so, exactly like `maps`
-- (032: CREATE POLICY "maps_all_anon" ON maps FOR ALL USING (true) WITH CHECK (true)), access is open and the
-- GM-only rule is enforced by the PIN-locked GM view, not by RLS. created_by is a free uuid (players.id), unconstrained.
CREATE TABLE IF NOT EXISTS campaign_nav_pins (
  id           uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  campaign_id  uuid NOT NULL REFERENCES campaigns(id) ON DELETE CASCADE,
  name         text NOT NULL,
  x            real NOT NULL,
  y            real NOT NULL,
  on_lane_hint boolean NOT NULL DEFAULT false,
  note         text,
  created_by   uuid,
  created_at   timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS campaign_nav_pins_campaign_idx ON campaign_nav_pins (campaign_id);

ALTER TABLE campaign_nav_pins ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "campaign_nav_pins_all_anon" ON campaign_nav_pins;
CREATE POLICY "campaign_nav_pins_all_anon" ON campaign_nav_pins FOR ALL USING (true) WITH CHECK (true);
